from pathlib import Path
import json

p=Path('app/LeagueApp.tsx')
s=p.read_text()

def rep(old,new,name):
    global s
    if old not in s:
        raise SystemExit('missing '+name)
    s=s.replace(old,new,1)

def block(start,end,new,name):
    global s
    a=s.find(start)
    b=s.find(end,a)
    if a<0 or b<0:
        raise SystemExit('missing block '+name)
    s=s[:a]+new+s[b:]

rep('const RELEASE_VERSION = "1.4.7.1";','const RELEASE_VERSION = "1.4.7.3";','version')
rep('import WeeklyPicksShareButton from "./WeeklyPicksShareButton";','import WeeklyPicksShareButton from "./WeeklyPicksShareButton";\nimport DataShareButton from "./DataShareButton";','import')
rep('<button className={styles.button} onClick={shareForm}>Share form</button>','<button className={styles.shareGold} onClick={shareForm}><span aria-hidden="true">▣</span><strong>Share current form</strong><small>Share as a formatted image</small></button>','form share')
rep('<Heading eyebrow={gameweek?`GAMEWEEK ${gameweek.number}`:"RESULTS"} title="Results" actions={<button className={styles.button} onClick={onRefresh}>Refresh displayed data</button>}>','<Heading eyebrow={gameweek?`GAMEWEEK ${gameweek.number}`:"RESULTS"} title="Results" actions={<div className={styles.headingActions}><DataShareButton title={`Gameweek ${gameweek?.number??"—"} Results`} subtitle="Selected Bounce BTTS fixtures and current outcomes" columns={["PLAYER","FIXTURE","SCORE","STATUS","PTS"]} rows={selected.map(({prediction,fixture,profile})=>[profile.display_name,`${fixture.home_team} v ${fixture.away_team}`,fixture.home_score==null?"—":`${fixture.home_score}-${fixture.away_score}`,fixture.status,prediction.points_awarded==null?"—":prediction.points_awarded])} fileName={`bounce-btts-gw${gameweek?.number??"results"}-results.jpg`} label="Share results" compact/><button className={styles.button} onClick={onRefresh}>Refresh displayed data</button></div>}>','results share')
rep('<Heading eyebrow="EST 2024 · SEASON ARCHIVE" title="League History">','<Heading eyebrow="EST 2024 · SEASON ARCHIVE" title="League History" actions={selected?<DataShareButton title={`${selected.label} Final Table`} subtitle={`Bounce BTTS League archive · ${selected.gameweeks} gameweeks`} columns={["POS","PLAYER","P","W","S-N","0-0","PTS"]} rows={selected.standings.map((row,index)=>[index+1,row.name,row.played,row.wins,row.oneSided??Math.max(0,row.points-(3*row.wins)+row.zeroZeroCount),row.zeroZeroCount,row.points])} fileName={`bounce-btts-${selected.label.replace("/","-")}-archive.jpg`} label="Share archive table" compact/>:undefined}>','history share')
rep('{view==="table" && <LeagueTable standings={standings} seasonLabel={seasonLabel} gameweek={gameweek??null} entryFee={entryFee}/>}','{view==="table" && <LeagueTable standings={standings} seasonLabel={seasonLabel} gameweek={gameweek??null} entryFee={entryFee} fixtures={fixtures} predictions={predictions}/>}','league props')
rep('<button className={styles.linkButton} onClick={()=>setView("table")}>Full table →</button>','<div className={styles.panelActions}><button className={styles.linkButton} onClick={()=>setView("table")}>Full table →</button><ShareTableButton compact rows={standings} seasonLabel={seasonLabel} gameweekNumber={gameweek?.number??null} prizePot={profiles.length*entryFee}/></div>','dashboard table actions')
s=s.replace('<div className={styles.tableActions}><ShareTableButton compact rows={standings} seasonLabel={seasonLabel} gameweekNumber={gameweek?.number??null} prizePot={profiles.length*entryFee}/></div>','',1)

league=r'''function LeagueTable({standings,seasonLabel,gameweek,entryFee,fixtures,predictions}:{standings:Standing[];seasonLabel:string;gameweek:Gameweek|null;entryFee:number;fixtures:Fixture[];predictions:Prediction[]}){
  const prizePot=standings.length*entryFee;
  const fixtureById=new Map(fixtures.map(f=>[f.id,f]));
  const completed=predictions.map(prediction=>({prediction,fixture:fixtureById.get(prediction.fixture_id)})).filter((x):x is {prediction:Prediction;fixture:Fixture}=>Boolean(x.fixture&&x.fixture.home_score!=null&&x.fixture.away_score!=null&&finishedStatuses.includes(x.fixture.status)));
  const selected=predictions.map(prediction=>({prediction,fixture:fixtureById.get(prediction.fixture_id)})).filter((x):x is {prediction:Prediction;fixture:Fixture}=>Boolean(x.fixture));
  const insights=standings.map(row=>{const done=completed.filter(x=>x.prediction.member_id===row.id);const picks=selected.filter(x=>x.prediction.member_id===row.id);const goals=done.reduce((sum,x)=>sum+Number(x.fixture.home_score??0)+Number(x.fixture.away_score??0),0);const home=done.filter(x=>(x.fixture.home_score??0)>(x.fixture.away_score??0)).length;const away=done.filter(x=>(x.fixture.away_score??0)>(x.fixture.home_score??0)).length;const draws=done.filter(x=>(x.fixture.home_score??0)===(x.fixture.away_score??0)).length;const comps=new Map<string,number>();picks.forEach(x=>{const c=competitionDisplayName(x.fixture);comps.set(c,(comps.get(c)??0)+1)});const favourite=[...comps.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0]?.[0]??"—";return {...row,goals,average:done.length?goals/done.length:0,home,away,draws,favourite}});
  const goalKing=[...insights].sort((a,b)=>b.goals-a.goals||b.wins-a.wins)[0];const homeHunter=[...insights].sort((a,b)=>b.home-a.home)[0];const awayHunter=[...insights].sort((a,b)=>b.away-a.away)[0];const drawMagnet=[...insights].sort((a,b)=>b.draws-a.draws)[0];const bttsKing=[...insights].sort((a,b)=>b.wins-a.wins||b.points-a.points)[0];const leagueGoals=completed.reduce((sum,x)=>sum+Number(x.fixture.home_score??0)+Number(x.fixture.away_score??0),0);
  const facts=[{label:"GOAL MAGNET",value:goalKing?.goals?goalKing.name:"—",detail:goalKing?.goals?`${goalKing.goals} goals in finished picks`:"Waiting for finished picks"},{label:"BTTS KING",value:bttsKing?.wins?bttsKing.name:"—",detail:bttsKing?.wins?`${bttsKing.wins} BTTS wins`:"No BTTS wins yet"},{label:"HOME-WIN HUNTER",value:homeHunter?.home?homeHunter.name:"—",detail:homeHunter?.home?`${homeHunter.home} selected matches ended home wins`:"No trend yet"},{label:"AWAY-WIN HUNTER",value:awayHunter?.away?awayHunter.name:"—",detail:awayHunter?.away?`${awayHunter.away} selected matches ended away wins`:"No trend yet"},{label:"DRAW MAGNET",value:drawMagnet?.draws?drawMagnet.name:"—",detail:drawMagnet?.draws?`${drawMagnet.draws} selected matches ended level`:"No trend yet"}];
  return <section className={styles.leaguePage}><Heading eyebrow={`SEASON ${seasonLabel} · ${gameweek?`GAMEWEEK ${gameweek.number}`:""} · EST 2024`} title="League Table" actions={<span className={styles.shareInline}><ShareTableButton rows={standings} seasonLabel={seasonLabel} gameweekNumber={gameweek?.number??null} prizePot={prizePot}/></span>}><p>S-N = score–nil +1. Ties: fewest 0–0 results, most BTTS wins, then alphabetical.</p></Heading><div className={`${styles.panel} ${styles.table} ${styles.fullLeagueTable} ${styles.enhancedTableShell} ${styles.leagueTableFirst}`}><div className={`${styles.tableRow} ${styles.header}`}><span>POS</span><span>PLAYER</span><span>P</span><span>W</span><span>S-N</span><span>0-0</span><span>PTS</span></div>{standings.map((r,i)=><div key={r.id} className={`${styles.tableRow} ${i===0?styles.leader:""} ${i<3?styles.tableRowTopThree:""}`}><span className={styles.positionCell}>{i===0?"🏆":i+1}</span><strong>{r.name}</strong><span>{r.played}</span><span>{r.wins}</span><span>{r.oneSided}</span><span>{r.zeroZeroCount}</span><b>{r.points}</b></div>)}</div><div className={styles.leagueStatsBand}><article><span>LEAGUE LEADER</span><strong>{standings[0]?.name??"—"}</strong><small>{standings[0]?`${standings[0].points} pts`:"No scores yet"}</small></article><article><span>SEASON POT</span><strong>£{prizePot.toFixed(0)}</strong><small>{standings.length} active players</small></article><article><span>GOALS IN PICKS</span><strong>{leagueGoals}</strong><small>Finished selected fixtures</small></article><article><span>FINISHED PICKS</span><strong>{completed.length}</strong><small>{predictions.length} selections recorded</small></article></div><div className={styles.seasonFacts}>{facts.map(f=><article key={f.label}><span>{f.label}</span><strong>{f.value}</strong><small>{f.detail}</small></article>)}</div><div className={`${styles.panel} ${styles.playerInsightPanel}`}><div className={styles.panelHeading}><div><div className={styles.title}>PLAYER TENDENCIES</div><h3>Season selection stats</h3></div></div><div className={styles.playerInsightGrid}>{insights.map(r=><article key={r.id} className={styles.playerInsightCard}><header><strong>{r.name}</strong><span>{r.points} pts</span></header><div><span>TOTAL GOALS</span><b>{r.goals}</b></div><div><span>AVG GOALS / PICK</span><b>{r.average?r.average.toFixed(1):"—"}</b></div><div><span>RESULT SPLIT</span><b>{r.home}H · {r.draws}D · {r.away}A</b></div><footer><span>Most picked competition</span><strong>{r.favourite}</strong></footer></article>)}</div></div></section>
}
'''
block('function LeagueTable(','function ResultsPage(',league,'league table')

adminCall='<AdminPage active={adminView} setActive={setAdminView} isUltimate={effectiveRole==="ultimate_admin"} readOnly={isReadOnly} demoMode={isDemo} onEmulate={(id)=>{if(id===initialProfile.id)return notice("You are already viewing your own account.");setEmulatedProfileId(id);setView("dashboard")}} gameweek={gameweek??null} nextGameweek={initialGameweeks.find(g=>g.number===(gameweek?.number??0)+1)??null} profiles={profiles} fixtures={currentFixtures} predictions={currentPredictions} adjustments={adjustments} notice={notice} onChanged={()=>refreshLiveData(false)}/>'
adminCall2='<AdminPage active={adminView} setActive={setAdminView} isUltimate={effectiveRole==="ultimate_admin"} readOnly={isReadOnly} demoMode={isDemo} onEmulate={(id)=>{if(id===initialProfile.id)return notice("You are already viewing your own account.");setEmulatedProfileId(id);setView("dashboard")}} gameweek={gameweek??null} nextGameweek={initialGameweeks.find(g=>g.number===(gameweek?.number??0)+1)??null} profiles={profiles} fixtures={currentFixtures} predictions={currentPredictions} adjustments={adjustments} entryFee={entryFee} notice={notice} onChanged={()=>refreshLiveData(false)}/>'
rep(adminCall,adminCall2,'admin call')
admin=r'''function AdminPage({active,setActive,isUltimate,readOnly,demoMode,onEmulate,gameweek,nextGameweek,profiles,fixtures,predictions,adjustments,entryFee,notice,onChanged}:{active:AdminView;setActive:(v:AdminView)=>void;isUltimate:boolean;readOnly:boolean;demoMode:boolean;onEmulate:(id:string)=>void;gameweek:Gameweek|null;nextGameweek:Gameweek|null;profiles:Profile[];fixtures:Fixture[];predictions:Prediction[];adjustments:ScoreAdjustment[];entryFee:number;notice:(m:string)=>void;onChanged:()=>void}){const wrap=(node:ReactNode)=><fieldset disabled={readOnly} className={readOnly?styles.readOnlyControls:""} style={{border:0,padding:0,margin:0,minWidth:0}}>{node}</fieldset>;return <section className={styles.adminPage}><Heading eyebrow="ADMIN CONTROL" title="League Management"><p>{isUltimate?"Full league, user and security administration.":"Manage selections, fixtures, results and gameweek status."}</p></Heading><div className={styles.adminTabs}>{(["users","selections","fixtures","results","gameweek","seasons"] as AdminView[]).filter(v=>v!=="users"||isUltimate).map(v=><button key={v} className={active===v?styles.active:""} onClick={()=>setActive(v)}>{v[0].toUpperCase()+v.slice(1)}</button>)}</div><div className={`${styles.panel} ${styles.adminPanel}`}>{readOnly&&<div className={styles.demoNotice}>Read-only view — controls are disabled.</div>}{active==="users"&&isUltimate&&(demoMode?<DemoUsersAdmin profiles={profiles}/>:wrap(<><PaymentTracker profiles={profiles} entryFee={entryFee} notice={notice}/><UsersAdmin notice={notice} onEmulate={onEmulate}/></>))}{active==="selections"&&wrap(<SelectionsAdmin gameweek={gameweek} profiles={profiles} fixtures={fixtures} predictions={predictions} adjustments={adjustments} notice={notice} onChanged={onChanged}/>) }{active==="fixtures"&&wrap(<FixturesAdmin gameweek={gameweek} nextGameweek={nextGameweek} notice={notice} onChanged={onChanged}/>) }{active==="results"&&wrap(<ResultsAdmin gameweek={gameweek} fixtures={fixtures} predictions={predictions} notice={notice} onChanged={onChanged}/>) }{active==="gameweek"&&wrap(<GameweekAdmin gameweek={gameweek} notice={notice} onChanged={onChanged}/>) }{active==="seasons"&&wrap(<SeasonsAdmin notice={notice} onChanged={onChanged}/>)}</div></section>}

function PaymentTracker({profiles,entryFee,notice}:{profiles:Profile[];entryFee:number;notice:(m:string)=>void}){const [seasonId,setSeasonId]=useState("");const [paid,setPaid]=useState<Record<string,boolean>>({});const [loading,setLoading]=useState(true);async function load(){const client=createClient();const season=await client.from("seasons").select("id").eq("is_current",true).maybeSingle();const id=season.data?.id??"";setSeasonId(id);if(id){const rows=await client.from("season_memberships").select("profile_id,paid").eq("season_id",id);setPaid(Object.fromEntries((rows.data??[]).map((r:any)=>[r.profile_id,Boolean(r.paid)])))}setLoading(false)}useEffect(()=>{load()},[]);async function toggle(id:string){if(!seasonId)return;const next=!paid[id];const client=createClient();const r=await client.from("season_memberships").update({paid:next,paid_at:next?new Date().toISOString():null}).eq("season_id",seasonId).eq("profile_id",id);if(r.error)return notice(r.error.message);setPaid(v=>({...v,[id]:next}));notice(next?"Entry fee marked paid":"Entry fee marked unpaid")}const active=profiles.filter(p=>p.active&&p.role!=="guest");const count=active.filter(p=>paid[p.id]).length;return <div className={styles.paymentTracker}><div className={styles.adminPaymentSummary}><article><span>ENTRY FEE</span><strong>£{entryFee.toFixed(0)}</strong><small>per member</small></article><article><span>PAID</span><strong>{count}/{active.length}</strong><small>£{(count*entryFee).toFixed(0)} received</small></article><article><span>OUTSTANDING</span><strong>£{((active.length-count)*entryFee).toFixed(0)}</strong><small>{active.length-count} member{active.length-count===1?"":"s"}</small></article></div>{loading?<div className={styles.notice}>Loading payment status…</div>:<div className={styles.paymentGrid}>{active.map(p=><button type="button" key={p.id} onClick={()=>toggle(p.id)} className={`${styles.paymentMember} ${paid[p.id]?styles.paymentPaid:styles.paymentUnpaid}`}><strong>{p.display_name}</strong><span>{paid[p.id]?"Paid ✓":`£${entryFee.toFixed(0)} unpaid`}</span></button>)}</div>}</div>}

'''
block('function AdminPage(','function UsersAdmin(',admin,'admin page')
s=s.replace('summary:"Visible Bounce identity refresh and compact admin browser layouts"','summary:"League table cleanup, season insights, gold sharing and entry-fee tracking"',1)
s=s.replace('changes:["Ultimate Admin emulation now has a persistent Exit emulation control and correctly resolves Demo Guest profiles"','changes:["Full League now puts the league table first and removes the redundant separate top-three showcase","New season insights track selected-match goals and home/away/draw tendencies","Share actions use a prominent gold treatment in top-right action areas on browser and mobile","Ultimate Admin can track current-season Paid / Unpaid entry fees with received and outstanding totals","Ultimate Admin emulation now has a persistent Exit emulation control and correctly resolves Demo Guest profiles"',1)
p.write_text(s)

p=Path('app/ShareTableButton.tsx')
s=p.read_text()
old='''  return (\n    <span className={`tableShareControl ${compact ? "compact" : ""} ${className}`.trim()}>\n      <button type="button" onClick={share} disabled={busy}>\n        {busy ? "Creating JPEG…" : compact ? "Share snapshot" : "Share table snapshot"}\n      </button>\n      {message && <small>{message}</small>}\n    </span>\n  );'''
new='''  return (\n    <span className={`tableShareControl ${compact ? "compact" : ""} ${className}`.trim()}>\n      <button className="dataShareButton" type="button" onClick={share} disabled={busy}>\n        <span aria-hidden="true">▣</span><strong>{busy ? "Creating image…" : "Share league table"}</strong><small>Share as a formatted image</small>\n      </button>\n      {message && <small className="tableShareMessage">{message}</small>}\n    </span>\n  );'''
if old not in s: raise SystemExit('missing share table')
p.write_text(s.replace(old,new,1))

p=Path('app/release.module.css')
s=p.read_text()
s+='''\n\n/* v1.4.7.3 league-first view, gold share actions and payments */\n.headingActions,.panelActions{display:flex;align-items:center;justify-content:flex-end;gap:9px;flex-wrap:wrap}.shareInline{display:inline-flex}.shareGold,:global(.dataShareButton),:global(.dashboardPicksShareButton){min-height:46px;display:grid;grid-template-columns:26px auto;grid-template-rows:auto auto;column-gap:8px;align-items:center;border:1px solid #f1d59a;border-radius:10px;padding:8px 12px;background:linear-gradient(180deg,#f1d28e,#d5a953 58%,#c18e3e);color:#3d1320;font-weight:900;cursor:pointer;box-shadow:0 8px 22px rgba(190,139,49,.22);text-align:left}.shareGold>span,:global(.dataShareButton>span),:global(.dashboardPicksShareButton>span){grid-row:1/3;color:#5a1c2e}.shareGold>strong,:global(.dataShareButton>strong),:global(.dashboardPicksShareButton>strong){font-size:12px;color:#3d1320}.shareGold>small,:global(.dataShareButton>small),:global(.dashboardPicksShareButton>small){font-size:9px;color:#6b4026}.leagueTableFirst{margin-bottom:16px}.leagueStatsBand{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}.leagueStatsBand article,.seasonFacts article,.adminPaymentSummary article{background:linear-gradient(145deg,rgba(43,20,29,.96),rgba(20,16,21,.98));border:1px solid rgba(199,175,149,.24);border-radius:12px;padding:13px}.leagueStatsBand span,.seasonFacts span,.adminPaymentSummary span{display:block;color:#b99f8a;font-size:9px;font-weight:900}.leagueStatsBand strong,.seasonFacts strong,.adminPaymentSummary strong{display:block;color:#f2e4d3;font:700 20px Georgia,serif;margin-top:5px}.leagueStatsBand small,.seasonFacts small,.adminPaymentSummary small{display:block;color:#9f938c;font-size:10px;margin-top:4px}.seasonFacts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:18px}.seasonFacts article{border-top:2px solid #caa45e}.playerInsightGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.playerInsightCard{border:1px solid rgba(112,66,77,.4);border-radius:11px;padding:12px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.playerInsightCard header,.playerInsightCard footer{grid-column:1/-1;display:flex;justify-content:space-between}.playerInsightCard>div span,.playerInsightCard footer span{font-size:8px;color:#8f8781}.playerInsightCard footer strong{font-size:10px;color:#c9ad91}.adminPaymentSummary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:10px}.paymentTracker{margin-bottom:16px}.paymentGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.paymentMember{border-radius:10px;padding:10px;text-align:left;border:1px solid}.paymentMember strong,.paymentMember span{display:block}.paymentMember span{font-size:10px;margin-top:4px}.paymentPaid{background:rgba(66,132,89,.19);border-color:#548f68;color:#9ee0b1}.paymentUnpaid{background:rgba(174,112,49,.16);border-color:#a87845;color:#efc17d}@media(max-width:900px){.seasonFacts{grid-template-columns:repeat(3,minmax(0,1fr))}.paymentGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.heading{align-items:stretch;flex-direction:column}.headingActions,.panelActions{justify-content:flex-start}.shareGold,:global(.dataShareButton),:global(.dashboardPicksShareButton){width:100%}.leagueStatsBand{grid-template-columns:1fr 1fr}.seasonFacts,.playerInsightGrid{grid-template-columns:1fr}.adminPaymentSummary{grid-template-columns:1fr}.paymentGrid{grid-template-columns:1fr 1fr}}\n'''
p.write_text(s)

p=Path('package.json')
d=json.loads(p.read_text())
d['scripts']['build']='next build'
p.write_text(json.dumps(d,indent=2)+'\n')
